	private static Extension hiddenCopies(String... names) {
		Extension extension = new Extension(new SingletonSet());
		for (String name : names) {
			extension.addElement(new ExtensionElem(Var.of(name), name + "Copy"));
		}
		return extension;
	}

	private static Bound bound(String name) {
		return new Bound(Var.of(name));
	}

	private static BindingSetAssignment values(BindingSet... rows) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(rows));
		return values;
	}

	private static MapBindingSet row(Object... pairs) {
		MapBindingSet row = new MapBindingSet(pairs.length / 2);
		for (int index = 0; index < pairs.length; index += 2) {
			row.addBinding((String) pairs[index], (Value) pairs[index + 1]);
		}
		return row;
	}

	private static List<BindingSet> evaluate(TupleExpr expression) {
		return evaluate(expression, false);
	}

	private static List<BindingSet> evaluate(TupleExpr expression, boolean optimize) {
		return evaluate(expression, optimize, EmptyBindingSet.getInstance());
	}

	private static List<BindingSet> evaluate(TupleExpr expression, boolean optimize, BindingSet input) {
		TripleSource source = new TripleSource() {
			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}

			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(List.<Statement>of().iterator());
			}
		};
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		if (optimize) {
			expression = strategy.optimize(new QueryRoot(expression), new EvaluationStatistics(),
					input);
		}
		try (CloseableIteration<BindingSet> rows = strategy.precompile(expression)
				.evaluate(input)) {
			List<BindingSet> results = new ArrayList<>();
			while (rows.hasNext()) {
				results.add(rows.next());
			}
			return results;
		}
	}
